// Generated by scripts/refine_character_parts.py from the checked-in part
// meshes and the shared junction constants - do not edit by hand; rerun the
// pipeline instead. The values mirror the pipeline so the baked morphs and
// the runtime bindings can never drift apart.
#ifndef ENGINE_DEMO_CHARACTER_METRICS_GEN_HPP
#define ENGINE_DEMO_CHARACTER_METRICS_GEN_HPP
namespace demo
{
// Junction interface rings in part-local space (meters).
struct CharacterInterfaceRing
{
    float x = 0.0f;
    float y = 0.0f;
    float z = 0.0f;
    float radius = 0.0f;
};

struct CharacterMetrics
{
    CharacterInterfaceRing neckRing{0.0f, 0.5715f, 0.0016f, 0.076f};
    CharacterInterfaceRing shoulderRing{0.212f, 0.506f, -0.022f, 0.062f};
    CharacterInterfaceRing hipRing{0.114f, 0.022f, 0.007f, 0.072f};

    // Morph gains at a full slider sweep (morph weight 1.0). The runtime
    // weight is (value - default) / span, so per-unit binding offsets are
    // gain / span.
    float torsoHeightGain = 0.24f;
    float torsoWidthGain = 0.16f;
    float torsoMuscleGain = 0.14f;
    float neckWidthGain = 0.22f;
    float neckMuscleGain = 0.12f;
    float shoulderMuscleGain = 0.1f;
    float hipMuscleGain = 0.08f;

    // Slider spans (max - default) used to normalize morph weights.
    float heightSpan = 0.35f;
    float widthSpan = 0.45f;
    float muscleSpan = 0.55f;
    float headSizeSpan = 0.50f;
    float muzzleSpan = 0.60f;

    // Lowest leg-mesh vertex (foot sole) below the hip ring origin.
    float legFootY = -1.001f;

    // tail.curl: the baked tail_curl morph moves the tail_end interface ring
    // sideways by exactly this offset per unit weight; the runtime emits the
    // same offset as a JointTranslation binding on tail_end.
    float tailCurlRingDeltaX = 0.14f;
};

inline constexpr CharacterMetrics kCharacterMetrics{};

} // namespace demo

#endif // ENGINE_DEMO_CHARACTER_METRICS_GEN_HPP
